begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
create temp table game_test_results(line text);
grant all on game_test_results to anon, authenticated, debug_duel_game_engine;
grant usage on schema extensions to anon, authenticated, debug_duel_game_engine;
set local role anon;
select set_config('request.jwt.claims','{}',true);
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
reset role;
update public.matches set guest_user_id='f1000000-0000-4000-8000-000000000001' where id='e1000000-0000-4000-8000-000000000002';
grant debug_duel_game_engine to postgres;
set local role debug_duel_game_engine;
reset role;
select line from game_test_results;
rollback;
